def build_context(cfg: Config):
    # Security baseline (2026): TLS verification is always-on.
    # cfg.verify_tls is honoured when True; when False, verification
    # is still enforced — it may never be weakened by configuration
    # or environment.
    if cfg.verify_tls:
        return ssl.create_default_context()
    return ssl.create_default_context()
